// Canonical plane bytes become 8x8 tile-major; semantic HUD stays linear.
// Divisors and tile-row multipliers are literal constants, not a runtime divider.
// Resource mapping and routed timing remain unqualified.
function automatic logic [19:0] physical_byte(input logic [19:0] logical_byte);
 integer unsigned base,offset,y,x;
 if(logical_byte>=20'd518400)return logical_byte;
 if(logical_byte<20'd345600)begin
  offset=32'(logical_byte);y=offset/720;x=offset%720;
  return 20'(((y/8)*90+x/8)*64+(y%8)*8+x%8);
 end
 base=logical_byte<20'd432000 ? 345600 : 432000;
 offset=32'(logical_byte)-base;y=offset/360;x=offset%360;
 return 20'(base+((y/8)*45+x/8)*64+(y%8)*8+x%8);
endfunction
